const b = $('Webhook').first().json.body || {};
// O QUE SAI TAMBEM SE GUARDA (31/08). Ate aqui `fromMe` era descartado
// junto com grupo e newsletter, entao NADA do que a Nay responde -- nem
// do que o Tel digita no WhatsApp dela -- ficava gravado: 2.800 linhas em
// `mensagens`, todas 'recebida', zero 'enviada'. O efeito pratico foi eu
// diagnosticar conversa pela metade e propor resposta para corretor que o
// Tel ja tinha atendido.
// A mensagem que sai e gravada com status 'Enviado', e o `Reservar
// mensagens` so pega 'Recebido' -- entao ela entra no historico e o fluxo
// para sozinho, sem responder a si mesma.
if (b.isGroup || b.isNewsletter || b.broadcast || b.isStatusReply) return [];
if (b.type !== 'ReceivedCallback') return [];
const saindo = !!(b.fromMe || b.fromApi);
const legenda = (b.image && b.image.caption) || (b.video && b.video.caption) || (b.document && b.document.caption) || null; const texto = (b.text && b.text.message) ? b.text.message : (legenda || null);
// A CITACAO. O corretor quase nunca manda o codigo: ele responde
// citando o card que saiu no grupo, e o codigo esta la dentro. Ate
// 29/08 isso era jogado fora aqui na entrada, e a Nay recebia
// "Ainda disponivel?" sem imovel nenhum (caso Valois, 29/08).
// A Z-API entrega em `referencedMessage` -- confirmado no historico
// de execucoes do n8n. A forma INTERNA ainda nao foi vista, entao
// tenta os caminhos plausiveis e, se nenhum servir, guarda o que
// veio: o proximo caso se explica sozinho em vez de sumir calado.
// A Z-API NAO manda mensagem citada nesta configuracao: 22 payloads
// capturados em 30/08 e nenhum traz `referencedMessage`. Os campos sao
// isStatusReply chatLid connectedPhone waitingMessage isEdit isGroup
// isNewsletter instanceId messageId phone fromMe momment status chatName
// senderName photo broadcast adContext messageExpirationSeconds forwarded
// type fromApi text. O campo fica aqui defensivamente, para o dia em que
// a Z-API passar a mandar -- mas quem identifica o imovel hoje e o CARD
// COLADO, tratado no `Juntar mensagens`.
// Captura a estrutura de quem RESPONDE MARCANDO. A conclusao anterior
// ("a Z-API nao manda citacao") veio de 22 amostras que eram mensagens
// comuns -- nao havia resposta marcada entre elas, entao a ausencia do
// campo nao provava nada. Agora so grava quando ha sinal de citacao ou
// quando o corpo traz campo desconhecido, para nao encher a tabela.
const camposRaiz = Object.keys(b).filter(k => b[k] !== null && b[k] !== undefined).join(' ');
const CONHECIDOS = new Set(['isStatusReply','chatLid','connectedPhone','waitingMessage',
  'isEdit','isGroup','isNewsletter','instanceId','messageId','phone','fromMe','momment',
  'status','chatName','senderName','photo','broadcast','adContext',
  'messageExpirationSeconds','forwarded','type','fromApi','text','image','audio','video',
  'document','sticker','reaction','reactionBy','notification','participantPhone',
  'participantLid','senderPhoto','isGroupMessage']);
const novos = Object.keys(b).filter(k => !CONHECIDOS.has(k));
const desc = v => v === null || v === undefined ? 'nulo'
  : Array.isArray(v) ? 'lista[' + v.length + ']'
  : typeof v === 'object' ? '{' + Object.keys(v).join(',') + '}'
  : typeof v === 'string' ? 'texto(' + v.length + ')' : typeof v;
const estrutura = novos.length
  ? novos.map(k => k + '=' + desc(b[k])).join(' | ')
  : null;

const ref = b.referencedMessage || null;
// `referenceMessageId` e o nome REAL do campo (visto em payload_estrutura,
// 01/09). So o ID chega, nunca o texto -- entao serve para saber que ELE
// respondeu citando algo, e ela perguntar de qual imovel se trata.
const refId = b.referenceMessageId || (ref && ref.messageId) || null;
let citado = null;
if (ref) {
  if (typeof ref === 'string') citado = ref;
  else citado = (ref.text && ref.text.message) || ref.message || ref.body
             || (ref.image && ref.image.caption)
             || (ref.video && ref.video.caption) || null;
  if (!citado) { try { citado = JSON.stringify(ref).slice(0, 900); } catch (e) { citado = null; } }
}
// TEMPORARIO (31/08): descobrir onde a Z-API poe a URL da imagem, para
// decidir se da para a Nay VER a foto. 12% das mensagens sao imagem (346
// em 30 dias) e hoje ela so diz que nao consegue abrir.
// Guarda apenas NOMES DE CAMPO e tipo, nunca o valor -- mesma disciplina
// da captura de citacao, que respondeu em 22 amostras o que seis palpites
// nao responderam. Apagar assim que o campo estiver conhecido.
let dbgImg = null;
if (b.image || b.video || b.document) {
  const desc = v => v === null || v === undefined ? 'nulo'
    : typeof v === 'object' ? '{' + Object.keys(v).join(',') + '}'
    : typeof v === 'string' ? 'texto(' + v.length + ')' : typeof v;
  dbgImg = ['image','video','document']
    .filter(k => b[k]).map(k => k + '=' + desc(b[k])).join(' | ');
}
let origem = 'texto';
// REACAO e FIGURINHA vem ANTES de imagem: figurinha costuma chegar como
// imagem na Z-API, e cairia em 'imagem' -- fazendo a Nay dizer "nao
// consigo abrir esse arquivo" para um 👍🏼. Foi o que aconteceu com o Moacy
// em 31/08: ele reagiu com joinha na mensagem DELA e recebeu o pedido de
// mandar o codigo do imovel.
if (b.reaction || b.reactionBy || b.isReaction) origem = 'reacao';
else if (b.sticker || (b.image && b.image.isSticker)) origem = 'figurinha';
else if (b.audio) origem = 'audio';
else if (b.image) origem = 'imagem';
else if (b.document) origem = 'documento';
else if (b.video) origem = 'video';
else if (!texto) origem = 'outro';
return [{ json: {
  telefone: String(b.phone || ''),
  nome: b.senderName || b.chatName || null,
  texto: texto,
  origem: origem,
  message_id: b.messageId || null,
  citado: citado,
    citadoId: refId,
  saindo: saindo,
  dbg_img: dbgImg,
  dbg_raiz: camposRaiz,
  dbg_estrutura: estrutura
} }];

const itens = $input.all().map(i => i.json).filter(m => m && m.id);
if (itens.length === 0) return [];
itens.sort((a, b) => a.id - b.id);
const nomeItem = itens.find(m => m.nome);
const val = (m) => (m.texto && m.texto !== 'null') ? m.texto : '';
let texto = itens.map(val).filter(Boolean).join('\n');
// 'outro' fica de FORA: e o que nao e texto nem arquivo conhecido --
// reacao com emoji, figurinha, enquete. Tratar isso como arquivo fez
// ela dizer ao Moacy "nao consigo abrir esse arquivo" quando ele nao
// tinha mandado arquivo nenhum (31/08, 19:23).
const nt = [...new Set(itens.filter(m => !val(m))
  .map(m => m.origem || 'outro')
  .filter(o => o !== 'outro' && o !== 'reacao' && o !== 'figurinha'))];
// O QUE O CORRETOR FALOU, sem envelope de sistema nenhum. E este que
// vai ao portao de fotos: os envelopes abaixo sao escritos por NOS, e
// um deles tinha a palavra 'fotos' dentro.
let textoCru = texto;
let transcrito = '';
try { const tr = $('Transcrever').all(); if (tr && tr.length) { transcrito = String(tr[0].json.text || tr[0].json.transcription || '').trim(); } } catch (e) { transcrito = ''; }
if (transcrito) {
  textoCru = transcrito;
  texto = '(o corretor mandou um audio. transcricao: "' + transcrito + '") Antes de enviar qualquer material, repita em uma linha o que voce entendeu e peca confirmacao.';
} else if (!texto && nt.length) {
  const nomes = { audio: 'um audio', imagem: 'uma imagem', documento: 'um arquivo', video: 'um video', outro: 'algo que nao e texto' };
  const lista = nt.map(o => nomes[o] || nomes.outro).join(' e ');
  texto = '(informacao de sistema, nao repita isso literalmente) o corretor enviou ' + lista + ' e nenhum texto junto. Voce nao consegue abrir nem ouvir esse tipo de arquivo. Responda em uma linha, no seu tom, dizendo que nao consegue abrir ' + lista + ' e pedindo para ele escrever a mensagem ou mandar o codigo do imovel. Nunca finja que viu ou ouviu o conteudo.';
}
// A citacao vai SEPARADA do texto, nunca colada nele. Se fosse
// colada, o card dela citado de volta -- que termina em "quer que
// eu mande as fotos?" -- dispararia envio de foto sem ninguem ter
// pedido. A citacao serve para achar o IMOVEL, o pedido se le so
// no que o corretor escreveu.
const citado = (itens.map(m => m.citado).filter(Boolean)[0]) || null;
// O CARD COLADO. Levantado em 30/08 capturando a estrutura do payload:
// a Z-API NAO manda mensagem citada (nao existe `referencedMessage` nos
// 22 payloads observados). O que o corretor faz de verdade e COLAR ou
// ENCAMINHAR o card do grupo para dizer de qual imovel fala -- o texto
// chega inteiro, entao nunca houve dado faltando.
// O defeito era outro: ela lia o card, buscava o codigo e devolvia o
// MESMO card de volta. A Samira mandou o 2943 e recebeu o 2943.
const mCard = texto.match(/C[óo]digo:\s*(\d{3,5})/i);
if (mCard && /[📍•]/.test(texto)) {
  texto = '(informacao de sistema, nao repita isso ao corretor) ele COLOU o card do imovel '
        + mCard[1] + ' para dizer de qual imovel esta falando. NAO mande esse card de volta, '
        + 'ele acabou de mandar. Siga de onde a conversa estava, tratando o ' + mCard[1]
        + ' como o imovel escolhido. Mensagem dele: ' + texto;
}
// OR entre as mensagens do lote: se o corretor mandou duas linhas e a
// pergunta da unidade esta na segunda, a parede tem que valer igual.
const pedeUnidade = itens.some(m => m.pede_unidade === true);
// Visita pedida em QUALQUER mensagem do lote vale para o turno todo.
const pedeVisita = itens.some(m => m.pede_visita === true);
// O aviso e o mesmo para todas as mensagens do lote (depende do
// telefone, nao do texto): basta o primeiro que veio preenchido.
const focoAviso = (itens.map(m => m.foco_aviso).filter(Boolean)[0]) || null;
// Pedido de foto em QUALQUER mensagem do lote vale para o turno todo --
// e o portao de envio le o texto junto, entao tem que ser OR aqui.
const vaoSairFotos = itens.some(m => m.manda_fotos === true);
// E os negocios se SOMAM: 'locacao' numa linha e 'venda' na outra e o
// caso que quebrou -- ela mandou so os de venda.
const negs = new Set();
for (const m of itens) {
  const x = m.negocio_pedido;
  if (x === 'ambos') { negs.add('venda'); negs.add('locacao'); }
  else if (x) negs.add(x);
}
const negocioPedido = negs.size > 1 ? 'ambos' : (negs.values().next().value || null);
// Ele respondeu citando alguma mensagem? So o ID chega, nunca o texto.
// `citado_id` (snake) e o nome que vem do RETURNING do Postgres.
const citadoId = (itens.map(m => m.citado_id).filter(Boolean)[0]) || null;
// O imovel da mensagem que ele marcou, quando a gente consegue casar.
const codigoCitado = (itens.map(m => m.codigo_citado).filter(Boolean)[0]) || null;
// Uniao dos codigos que ele escreveu, sem os valores.
const codigosDele = [...new Set(itens.flatMap(m => m.codigos_citados || []))];
return [{ json: { perguntaAberta: itens.some(m => m.pergunta_aberta === true), pedeUnidade: pedeUnidade, citadoId: citadoId, codigoCitado: codigoCitado, codigosDele: codigosDele, telefone: itens[0].telefone, nome: nomeItem ? nomeItem.nome : null, pedeVisita: pedeVisita, focoAviso: focoAviso, vaoSairFotos: vaoSairFotos, negocioPedido: negocioPedido, opcoesCitacao: (itens.map(m => m.opcoes_citacao).filter(Boolean)[0]) || null, nomePessoa: (itens.map(m => m.nome_pessoa).filter(Boolean)[0]) || null, texto: texto, textoCru: textoCru, citado: citado, naoTexto: nt, ids: itens.map(m => m.id), qtd: itens.length } }];

// >>> segundo numero do Tel (28/09)
const TELS_DO_TEL = ['[telefone …7316]', '[telefone …6408]'];
const _finalDoTel = (x) => String(x == null ? '' : x).replace(/\D/g, '').slice(-8);
const _FINAIS_DO_TEL = TELS_DO_TEL.map(_finalDoTel);
const ehTelDoTel = (x) => _FINAIS_DO_TEL.indexOf(_finalDoTel(x)) !== -1;
// <<< segundo numero do Tel
const j = $('Juntar mensagens').first().json;
const t = (j.texto || '').trim();
// >>> escolha do posta (patch_escolha_do_posta_n8n.js)
// Com pergunta aberta ao Tel, o numero sozinho e a RESPOSTA dela -- e
// quem a resolve e o publicador. Sem esta parede ele recebe o card no
// privado ao mesmo tempo em que o imovel sai nos grupos: os ramos do
// fluxo rodam em PARALELO.
//
// So para o TEL: o mesmo numero vindo de um corretor continua pedindo
// o card, que e o caminho dele desde sempre.
if (j.perguntaAberta === true && ehTelDoTel(j.telefone)) return [];
// <<< escolha do posta
if (!/^\d{3,5}$/.test(t)) return [];
return [{ json: { codigo: parseInt(t, 10), telefone: j.telefone, nome: j.nome } }];

const r = $json;
if (!r || !r.codigo) return [{ json: { bloco: 'CODIGO NAO ENCONTRADO NA BASE' } }];
const n = v => (v == null ? 0 : Number(v));
const f = v => Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const MOB = {
  'mobiliado (moveis + cama + tudo)': 'mobiliado (móveis + cama + tudo)',
  'semi-mobiliado (moveis planejados + ar)': 'semi-mobiliado (móveis planejados + ar)',
  'so ar-condicionado': 'só ar-condicionado'
};
const apto = /apartamento|cobertura|flat/i.test(r.tipo || '');
const condo = r.condominio_nome && !/n[ãa]o identificado/i.test(r.condominio_nome) ? r.condominio_nome : null;
if (r.e_parceiro) {
  return [{ json: { lead_in: 'Encontrei:', bloco: '📍 ' + (condo || r.tipo) + '\n• esse imovel e de parceria, nao da imob easy.', qtd_fotos: 0, avisos: 'E DE PARCEIRO' } }];
}
const temTx = /condom/i.test(r.incluso_aluguel || '');
const L = [];
L.push('📍 ' + (condo || r.tipo));
if (r.bairro) L.push('• Bairro: ' + r.bairro);
if (apto && r.sol) L.push('• apto ' + String(r.sol).toLowerCase());
if (n(r.area_util)) L.push('• ' + f(r.area_util) + 'm2');
if (n(r.quartos)) L.push('• ' + r.quartos + ' quartos' + (n(r.suites) ? ' sendo ' + r.suites + ' suíte' : ''));
if (n(r.vagas_cobertas)) L.push('• ' + r.vagas_cobertas + ' vagas cobertas');
else if (n(r.vagas)) L.push('• ' + r.vagas + ' vagas');
if (apto && r.mobilia) L.push('• ' + (MOB[r.mobilia] || r.mobilia));
if (n(r.taxa_condominio) && !temTx) L.push('• taxa de condomínio: ' + f(r.taxa_condominio));
if (n(r.valor_venda)) L.push('valor: ' + f(r.valor_venda));
if (n(r.valor_aluguel)) L.push('locação: ' + f(r.valor_aluguel) + (temTx ? ' (incluso a TX)' : ''));
L.push('Código: ' + r.codigo);
const avisos = [];
if (!r.disponivel) avisos.push('NAO DISPONIVEL');
if (r.bloqueado) avisos.push('BLOQUEADO');
if (!Number(r.qtd_fotos)) avisos.push('SEM FOTOS');
return [{ json: { lead_in: 'Encontrei:', bloco: L.join('\n'), qtd_fotos: Number(r.qtd_fotos), avisos: avisos.join(' | ') || 'ok' } }]

// >>> segundo numero do Tel (28/09)
const TELS_DO_TEL = ['[telefone …7316]', '[telefone …6408]'];
const _finalDoTel = (x) => String(x == null ? '' : x).replace(/\D/g, '').slice(-8);
const _FINAIS_DO_TEL = TELS_DO_TEL.map(_finalDoTel);
const ehTelDoTel = (x) => _FINAIS_DO_TEL.indexOf(_finalDoTel(x)) !== -1;
// <<< segundo numero do Tel
const tel = $('Juntar mensagens').first().json.telefone;
// PORTEIRO (29/08), mesma regra do `Preparar envio do agente`: so quem
// esta em `corretores` recebe. Aqui NAO ha cortesia -- um desconhecido
// cujo primeiro contato e um codigo puro ("1234") fica no silencio, e a
// cortesia sai quando ele escrever qualquer texto. Caso raro, e o preco
// de nao duplicar a mensagem nos dois caminhos.
// PORTEIRO, versao que falha FECHADA (30/08). A anterior tinha um buraco:
//   if (!g.aprovado && Number(g.msgs_antes || 0) > 0) return [];
// Se `g` viesse vazio -- referencia falhando, formato inesperado --
// `Number(undefined) > 0` da FALSO e a porta abria. Porteiro que nao sabe
// quem esta na frente tem que dizer nao, nao sim.
let g;
try { g = $('Gravar na fila').first().json || {}; } catch (e) { g = {}; }
const aprovado = g.aprovado === true;
const primeiraVez = g.msgs_antes === 0;   // exatamente zero, nunca "nao sei"
const pausado = g.pausado !== false;      // sem informacao, considera pausado
if (pausado && !ehTelDoTel(tel)) return [];
// Caminho de codigo puro: desconhecido nao recebe nem a cortesia --
// ela sai pelo caminho do agente quando ele escrever texto.
if (!aprovado) return [];
const m = $('Montar mensagem').first().json;
const fotos = $input.all().map(i => i.json.url).filter(Boolean);
const saida = [];
saida.push({ rota: 'send-text', pausa: 1, corpo: { phone: tel, message: m.lead_in } });
saida.push({ rota: 'send-text', pausa: 2, corpo: { phone: tel, message: m.bloco } });
for (const u of fotos) saida.push({ rota: 'send-image', pausa: 6, corpo: { phone: tel, image: u } });
return saida.map(x => ({ json: x }));

const j = $('Juntar mensagens').first().json;
const texto = j.texto || '';
if (/c[óo]digo\s*[:\-]?\s*\d{3,5}/i.test(texto) || /^\d{3,5}$/.test(texto.trim())) return [];
const norm = s => (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const GEN = /^(condominio|residencial|edificio|ed|cond)\s+/;
const t = norm(texto);
let melhor = null;
for (const item of $input.all()) {
  const nome = item.json.condominio_nome;
  let nuc = norm(nome);
  while (GEN.test(nuc)) nuc = nuc.replace(GEN, '');
  if (nuc.length < 4) continue;
  if (t.includes(nuc) && (!melhor || nuc.length > melhor.nuc.length)) melhor = { nome: nome, nuc: nuc };
}
if (!melhor) return [];
let quartos = 0;
const mq = t.match(/(\d)\s*(quartos?|qts?|qto|dormitorios?)/);
if (mq) quartos = parseInt(mq[1], 10);
let modo = 0;
if (/alug|locac|locar/.test(t)) modo = 1;
else if (/venda|vender|comprar|compra/.test(t)) modo = 2;
return [{ json: { condominio: melhor.nome, quartos: quartos, modo: modo } }];

// >>> segundo numero do Tel (28/09)
const TELS_DO_TEL = ['[telefone …7316]', '[telefone …6408]'];
const _finalDoTel = (x) => String(x == null ? '' : x).replace(/\D/g, '').slice(-8);
const _FINAIS_DO_TEL = TELS_DO_TEL.map(_finalDoTel);
const ehTelDoTel = (x) => _FINAIS_DO_TEL.indexOf(_finalDoTel(x)) !== -1;
// <<< segundo numero do Tel
const f = $('Achar condominio').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.codigo);
const n = v => (v == null ? 0 : Number(v));
const fmt = v => Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
let lista = rows;
if (f.quartos) lista = lista.filter(r => n(r.quartos) === f.quartos);
if (f.modo === 1) lista = lista.filter(r => n(r.valor_aluguel) > 0);
if (f.modo === 2) lista = lista.filter(r => n(r.valor_venda) > 0);
const total = lista.length;
const MAX = 8;
const mostra = lista.slice(0, MAX);
let msg;
if (total === 0) {
  msg = 'no ' + f.condominio + ' não tenho nada disponível com esse perfil no momento';
} else {
  const linhas = mostra.map(r => {
    const preco = f.modo === 1 ? (n(r.valor_aluguel) ? 'locação ' + fmt(r.valor_aluguel) : 'consultar') : (n(r.valor_venda) ? fmt(r.valor_venda) : (n(r.valor_aluguel) ? 'locação ' + fmt(r.valor_aluguel) : 'consultar'));
    const q = n(r.quartos) ? r.quartos + ' quartos' : (r.tipo || '');
    const a = n(r.area_util) ? ' — ' + fmt(r.area_util) + 'm2' : '';
    return '• ' + r.codigo + ' — ' + q + a + ' — ' + preco;
  });
  const cab = 'no ' + f.condominio + ' tenho ' + total + (total === 1 ? ' opção:' : ' opções:');
  const rodape = total > MAX ? '\n\nesses são os ' + MAX + ' primeiros. me diz quantos quartos ou o valor que eu filtro' : '\n\nme manda o código do que interessar que eu mando as fotos';
  msg = cab + '\n' + linhas.join('\n') + rodape;
}
// TESTE virou pergunta: ver ehTelDoTel.
const tel = $('Juntar mensagens').first().json.telefone;
if (!ehTelDoTel(tel)) return [];
return [{ json: { corpo: { phone: tel, message: msg } } }];

// >>> telefone na frente sem verbo (28/09)
const _UM_CODIGO_DEPOIS_DO_TEL = (x) => {
  const s = String(x == null ? '' : x);
  const m = /^\s*(?:@?nay\b[\s,;:.!?-]*)?((?:55[\s.-]*)?\(?\d{2}\)?[\s.-]*9?\d{4}[\s.-]*\d{4})\b/i.exec(s);
  if (!m) return false;
  const resto = s.slice(m.index + m[0].length);
